'use strict';

// Reproductions of INC-5521. Each race runs its two calls with the second one
// started 0..MAX_OFFSET event-loop ticks after the first, which walks through
// the interleavings the production store allows, then checks that the SKU
// counters agree with the order records.

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  OrderStateError
} = require('../src');

const MAX_OFFSET = 12;

function tick() {
  return new Promise(resolve => setImmediate(resolve));
}

async function afterTicks(n, fn) {
  for (let i = 0; i < n; i++) {
    await tick();
  }
  return fn();
}

async function setup(stock, options = {}) {
  const store = options.store || new Store();
  const svc = new InventoryService({ store, ...options, store });
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return { svc, store };
}

// Every unit is on hand, held by exactly one reserved order, or sold to
// exactly one committed order.
async function assertConsistent(svc, store, added) {
  const expected = {};
  for (const sku of Object.keys(added)) {
    expected[sku] = { reserved: 0, sold: 0 };
  }
  for (const key of await store.keys('order:')) {
    const order = await store.get(key);
    for (const { sku, qty } of order.items) {
      if (order.status === 'reserved') expected[sku].reserved += qty;
      if (order.status === 'committed') expected[sku].sold += qty;
    }
  }
  for (const [sku, total] of Object.entries(added)) {
    const snap = await svc.snapshot(sku);
    assert.deepEqual(
      snap,
      { sku, stock: total - expected[sku].sold, reserved: expected[sku].reserved, sold: expected[sku].sold },
      `counters for ${sku} disagree with the order records`
    );
    assert.ok(snap.stock - snap.reserved >= 0, `available for ${sku} went negative`);
  }
}

function assertOnlyErrors(results, ErrorType) {
  for (const result of results) {
    if (result.status === 'rejected') {
      assert.ok(result.reason instanceof ErrorType, `unexpected rejection: ${result.reason && result.reason.stack}`);
    }
  }
}

describe('INC-5521: concurrent checkout', () => {
  it('sells exactly the units on hand when 263 orders race for 250 (oversold drop)', async () => {
    const { svc, store } = await setup({ 'sneaker-limited': 250 });
    const results = await Promise.allSettled(
      Array.from({ length: 263 }, (_, i) => svc.reserve(`order-${i}`, [{ sku: 'sneaker-limited', qty: 1 }]))
    );
    assertOnlyErrors(results, InsufficientStockError);
    const confirmed = results.filter(r => r.status === 'fulfilled').map(r => r.value.orderId);
    assert.equal(confirmed.length, 250);

    await Promise.all(confirmed.map(orderId => svc.commit(orderId)));
    assert.deepEqual(await svc.snapshot('sneaker-limited'), { sku: 'sneaker-limited', stock: 0, reserved: 0, sold: 250 });
    await assertConsistent(svc, store, { 'sneaker-limited': 250 });
  });

  it('never lets bundles hold more than the stock on hand', async () => {
    const { svc, store } = await setup({ a: 30, b: 30 });
    const results = await Promise.allSettled(
      Array.from({ length: 40 }, (_, i) =>
        svc.reserve(`o${i}`, i % 2 ? [{ sku: 'a', qty: 1 }, { sku: 'b', qty: 1 }] : [{ sku: 'b', qty: 1 }, { sku: 'a', qty: 1 }])
      )
    );
    assertOnlyErrors(results, InsufficientStockError);
    assert.equal(results.filter(r => r.status === 'fulfilled').length, 30);
    await assertConsistent(svc, store, { a: 30, b: 30 });
  });

