'use strict';

/**
 * First-come, first-served mutual exclusion per key, within one process.
 *
 * Callers that share no key never wait for each other. A key's entry is
 * dropped as soon as nobody holds or waits for it, so memory tracks the keys
 * in use right now rather than every key ever locked.
 */
class KeyedLock {
  constructor() {
    // key -> callbacks waiting for it. A key is held while it has an entry.
    this.queues = new Map();
  }

  /** Number of keys currently held. */
  get size() {
    return this.queues.size;
  }

  /**
   * Run `fn` while holding every key in `keys`, and release them when it
   * settles, whether it resolves or throws. Keys are taken in sorted order,
   * so calls with overlapping key sets cannot deadlock each other. Code that
   * nests run() calls must nest them in one consistent order as well.
   */
  async run(keys, fn) {
    const ordered = [...new Set(keys)].sort();
    const held = [];
    try {
      for (const key of ordered) {
        // Sequential on purpose: taking keys one at a time in sorted order is
        // what rules out deadlock.
        await this.acquire(key);
        held.push(key);
      }
      return await fn();
    } finally {
      for (const key of held) {
        this.release(key);
      }
    }
  }

  acquire(key) {
    const queue = this.queues.get(key);
    if (!queue) {
      this.queues.set(key, []);
      return Promise.resolve();
    }
    return new Promise(resolve => queue.push(resolve));
  }

  release(key) {
    const queue = this.queues.get(key);
    const next = queue.shift();
    if (next) {
      next();
    } else {
      this.queues.delete(key);
    }
  }
}

module.exports = { KeyedLock };

