'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { KeyedLock } = require('../src/keyed-lock');

function tick() {
  return new Promise(resolve => setImmediate(resolve));
}

// Records how many calls are inside `fn` at once for each key.
function tracker() {
  const active = new Map();
  const peak = new Map();
  return {
    async work(keys, ticks = 3) {
      for (const key of keys) {
        active.set(key, (active.get(key) || 0) + 1);
        peak.set(key, Math.max(peak.get(key) || 0, active.get(key)));
      }
      for (let i = 0; i < ticks; i++) await tick();
      for (const key of keys) active.set(key, active.get(key) - 1);
    },
    peak
  };
}

describe('KeyedLock', () => {
  it('runs calls on the same key one at a time, in arrival order', async () => {
    const lock = new KeyedLock();
    const track = tracker();
    const order = [];
    await Promise.all(
      [0, 1, 2, 3, 4].map(i =>
        lock.run(['k'], async () => {
          order.push(i);
          await track.work(['k']);
        })
      )
    );
    assert.equal(track.peak.get('k'), 1);
