'use strict';

// Reproductions of INC-5521. Each race runs its two calls with the second one
// started 0..MAX_OFFSET event-loop ticks after the first, which walks through
// the interleavings the production store allows, then checks that the SKU
// counters agree with the order records.

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  OrderStateError
} = require('../src');

const MAX_OFFSET = 12;

function tick() {
  return new Promise(resolve => setImmediate(resolve));
}

async function afterTicks(n, fn) {
  for (let i = 0; i < n; i++) {
    await tick();
  }
  return fn();
}

async function setup(stock, options = {}) {
  const store = options.store || new Store();
  const svc = new InventoryService({ ...options, store });
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return { svc, store };
}

// Every unit is on hand, held by exactly one reserved order, or sold to
// exactly one committed order.
async function assertConsistent(svc, store, added) {
  const expected = {};
  for (const sku of Object.keys(added)) {
    expected[sku] = { reserved: 0, sold: 0 };
  }
  for (const key of await store.keys('order:')) {
    const order = await store.get(key);
    for (const { sku, qty } of order.items) {
      if (order.status === 'reserved') expected[sku].reserved += qty;
      if (order.status === 'committed') expected[sku].sold += qty;
    }
  }
  for (const [sku, total] of Object.entries(added)) {
    const snap = await svc.snapshot(sku);
    assert.deepEqual(
      snap,
      { sku, stock: total - expected[sku].sold, reserved: expected[sku].reserved, sold: expected[sku].sold },
      `counters for ${sku} disagree with the order records`
    );
    assert.ok(snap.stock - snap.reserved >= 0, `available for ${sku} went negative`);
  }
}

function assertOnlyErrors(results, ErrorType) {
  for (const result of results) {
    if (result.status === 'rejected') {
      assert.ok(result.reason instanceof ErrorType, `unexpected rejection: ${result.reason && result.reason.stack}`);
    }
  }
}

describe('INC-5521: concurrent checkout', () => {
  it('sells exactly the units on hand when 263 orders race for 250 (oversold drop)', async () => {
    const { svc, store } = await setup({ 'sneaker-limited': 250 });
    const results = await Promise.allSettled(
      Array.from({ length: 263 }, (_, i) => svc.reserve(`order-${i}`, [{ sku: 'sneaker-limited', qty: 1 }]))
    );
    assertOnlyErrors(results, InsufficientStockError);
    const confirmed = results.filter(r => r.status === 'fulfilled').map(r => r.value.orderId);
    assert.equal(confirmed.length, 250);

    await Promise.all(confirmed.map(orderId => svc.commit(orderId)));
    assert.deepEqual(await svc.snapshot('sneaker-limited'), { sku: 'sneaker-limited', stock: 0, reserved: 0, sold: 250 });
    await assertConsistent(svc, store, { 'sneaker-limited': 250 });
  });

  it('never lets bundles hold more than the stock on hand', async () => {
    const { svc, store } = await setup({ a: 30, b: 30 });
    const results = await Promise.allSettled(
      Array.from({ length: 40 }, (_, i) =>
        svc.reserve(`o${i}`, i % 2 ? [{ sku: 'a', qty: 1 }, { sku: 'b', qty: 1 }] : [{ sku: 'b', qty: 1 }, { sku: 'a', qty: 1 }])
      )
    );
    assertOnlyErrors(results, InsufficientStockError);
    assert.equal(results.filter(r => r.status === 'fulfilled').length, 30);
    await assertConsistent(svc, store, { a: 30, b: 30 });
  });

  it('two service instances on one store do not oversell (one per worker)', async () => {
    const store = new Store();
    const first = new InventoryService({ store });
    const second = new InventoryService({ store });
    await first.addStock('sneaker-limited', 10);
    const results = await Promise.allSettled(
      Array.from({ length: 30 }, (_, i) =>
        (i % 2 ? first : second).reserve(`o${i}`, [{ sku: 'sneaker-limited', qty: 1 }])
      )
    );
    assertOnlyErrors(results, InsufficientStockError);
    assert.equal(results.filter(r => r.status === 'fulfilled').length, 10);
    await assertConsistent(first, store, { 'sneaker-limited': 10 });
  });

  it('keeps every restock that lands while orders are reserving', async () => {
    const { svc, store } = await setup({ widget: 5 });
    const calls = [];
    for (let i = 0; i < 20; i++) {
      calls.push(svc.reserve(`o${i}`, [{ sku: 'widget', qty: 1 }]));
      if (i % 4 === 0) calls.push(svc.addStock('widget', 2));
    }
    assertOnlyErrors(await Promise.allSettled(calls), InsufficientStockError);
    await assertConsistent(svc, store, { widget: 15 });
  });

  it('keeps every unit from concurrent restocks of a new sku', async () => {
    const svc = new InventoryService();
    await Promise.all(Array.from({ length: 25 }, () => svc.addStock('fresh', 2)));
    assert.deepEqual(await svc.snapshot('fresh'), { sku: 'fresh', stock: 50, reserved: 0, sold: 0 });
  });
});

describe('INC-5521: races on one order', () => {
  const races = [
    {
      name: 'a retried reserve holds the units once (double hold on retry)',
      before: () => {},
      a: svc => svc.reserve('o1', [{ sku: 'widget', qty: 3 }]),
      b: svc => svc.reserve('o1', [{ sku: 'widget', qty: 3 }]),
      check: async (svc, results) => {
        assert.deepEqual(results.map(r => r.status), ['fulfilled', 'fulfilled']);
        assert.deepEqual(results[1].value, results[0].value);
        assert.equal(await svc.available('widget'), 7);
        await svc.release('o1');
        assert.equal(await svc.available('widget'), 10, 'a hold outlived its order');
      }
    },
    {
      name: 'a retried commit sells the units once (inflated sold)',
      before: svc => svc.reserve('o1', [{ sku: 'widget', qty: 3 }]),
      a: svc => svc.commit('o1'),
      b: svc => svc.commit('o1'),
      check: async (svc, results) => {
        assert.deepEqual(results.map(r => r.status), ['fulfilled', 'fulfilled']);
        assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
      }
    },
    {
      name: 'a repeated release returns the units once (negative reserved)',
      before: svc => svc.reserve('o1', [{ sku: 'widget', qty: 3 }]),
      a: svc => svc.release('o1'),
      b: svc => svc.release('o1'),
      check: async (svc, results) => {
        assert.deepEqual(results.map(r => r.status), ['fulfilled', 'fulfilled']);
        assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
      }
    },
    {
      name: 'commit racing release lets exactly one of them win',
      before: svc => svc.reserve('o1', [{ sku: 'widget', qty: 3 }]),
      a: svc => svc.commit('o1'),
      b: svc => svc.release('o1'),
      check: async (svc, results) => {
        const won = results.filter(r => r.status === 'fulfilled');
        assert.equal(won.length, 1, 'commit and release both succeeded');
        assertOnlyErrors(results, OrderStateError);
      }
    },
    {
      name: 'expire racing commit never releases the committed order',
      before: svc => svc.reserve('o1', [{ sku: 'widget', qty: 3 }]),
      a: svc => svc.commit('o1'),
      b: svc => svc.expire(),
      check: async (svc, results) => {
        const [commit, expire] = results;
        assert.equal(expire.status, 'fulfilled');
        if (commit.status === 'fulfilled') {
          assert.deepEqual(expire.value, []);
          assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
        } else {
          assert.ok(commit.reason instanceof OrderStateError);
          assert.deepEqual(expire.value, ['o1']);
          assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
        }
      }
    },
    {
      name: 'two expire runs release a stale order once',
      before: svc => svc.reserve('o1', [{ sku: 'widget', qty: 3 }]),
      a: svc => svc.expire(),
      b: svc => svc.expire(),
      check: async (svc, results) => {
        assert.deepEqual(results.map(r => r.value).flat(), ['o1']);
        assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
      }
    }
  ];

  for (const race of races) {
    it(race.name, async () => {
      for (let offset = 0; offset <= MAX_OFFSET; offset++) {
        // A negative TTL makes every reservation stale, so expire() is live in every race.
        const { svc, store } = await setup({ widget: 10 }, { reservationTtlMs: -1 });
        await race.before(svc);
        const results = await Promise.allSettled([race.a(svc), afterTicks(offset, () => race.b(svc))]);
        await race.check(svc, results).catch(err => {
          err.message = `offset ${offset}: ${err.message}`;
          throw err;
        });
        await assertConsistent(svc, store, { widget: 10 });
      }
    });
  }
});

describe('INC-5521: independent calls do not wait for each other', () => {
  // A store that stalls every read and write of one key until released.
  function stallingStore(stalledKey) {
    const inner = new Store();
    let resume;
    const gate = new Promise(resolve => {
      resume = resolve;
    });
    let stalling = false;
    const pass = async key => {
      if (stalling && key === stalledKey) await gate;
    };
    return {
      store: {
        async get(key) {
          await pass(key);
          return inner.get(key);
        },
        async set(key, value) {
          await pass(key);
          return inner.set(key, value);
        },
        keys: prefix => inner.keys(prefix)
      },
      stall() {
        stalling = true;
      },
      resume
    };
  }

  it('checkout on one sku completes while another sku is stalled', { timeout: 5000 }, async () => {
    const gated = stallingStore('sku:slow');
    const { svc } = await setup({ slow: 5, fast: 5 }, { store: gated.store });
    await svc.reserve('slow-release', [{ sku: 'slow', qty: 1 }]);
    gated.stall();

    let slowDone = false;
    const slow = Promise.all([
      svc.reserve('slow-order', [{ sku: 'slow', qty: 1 }]),
      svc.release('slow-release'),
      svc.addStock('slow', 1)
    ]).then(() => {
      slowDone = true;
    });

    await svc.addStock('fast', 1);
    await svc.reserve('fast-order', [{ sku: 'fast', qty: 2 }]);
    await svc.commit('fast-order');
    await svc.reserve('fast-release', [{ sku: 'fast', qty: 1 }]);
    await svc.release('fast-release');
    assert.deepEqual(await svc.snapshot('fast'), { sku: 'fast', stock: 4, reserved: 0, sold: 2 });
    assert.equal(slowDone, false, 'the stalled calls should still be waiting');

    gated.resume();
    await slow;
    assert.deepEqual(await svc.snapshot('slow'), { sku: 'slow', stock: 6, reserved: 1, sold: 0 });
  });
});

describe('store write failures', () => {
  it('keeps the SKU locked until every write of a failed update has landed', { timeout: 5000 }, async () => {
    const inner = new Store();
    let failing = false;
    let slowWrite;
    const store = {
      get: key => inner.get(key),
      async set(key, value) {
        if (failing && key === 'sku:b') throw new Error('store unavailable');
        if (failing && key === 'sku:a' && !slowWrite) {
          slowWrite = afterTicks(20, () => inner.set(key, value));
          return slowWrite;
        }
        return inner.set(key, value);
      },
      keys: prefix => inner.keys(prefix)
    };
    const { svc } = await setup({ a: 10, b: 10 }, { store });
    failing = true;
    const reserve = svc.reserve('o1', [{ sku: 'a', qty: 2 }, { sku: 'b', qty: 2 }]);
    const restock = afterTicks(3, () => svc.addStock('a', 1));
    await assert.rejects(reserve, /store unavailable/);
    await Promise.all([restock, slowWrite]);
    assert.equal((await svc.snapshot('a')).stock, 11, 'the restock was overwritten by the slow write');
  });
});

describe('INC-5521: mixed checkout load', () => {
  // Mulberry32: a small seeded PRNG so a failing seed can be replayed.
  function prng(seed) {
    let state = seed >>> 0;
    return () => {
      state = (state + 0x6d2b79f5) >>> 0;
      let t = state;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  // The same three methods as Store, with a random extra delay on every call.
  class JitterStore {
    constructor(random) {
      this.inner = new Store();
      this.random = random;
    }

    async jitter() {
      const ticks = Math.floor(this.random() * 4);
      for (let i = 0; i < ticks; i++) await tick();
    }

    async get(key) {
      await this.jitter();
      return this.inner.get(key);
    }

    async set(key, value) {
      await this.jitter();
      return this.inner.set(key, value);
    }

    async keys(prefix) {
      await this.jitter();
      return this.inner.keys(prefix);
    }
  }

  for (const seed of [1, 7, 42, 5521]) {
    it(`keeps counters and orders consistent (seed ${seed})`, async () => {
      const random = prng(seed);
      const pick = list => list[Math.floor(random() * list.length)];
      const skus = ['a', 'b', 'c', 'd'];
      const added = { a: 20, b: 20, c: 20, d: 20 };
      const { svc, store } = await setup(added, { store: new JitterStore(random), reservationTtlMs: -1 });

      const worker = async orderId => {
        const first = pick(skus);
        const items = [{ sku: first, qty: 1 + Math.floor(random() * 3) }];
        const second = pick(skus);
        if (second !== first) items.push({ sku: second, qty: 1 });
        const attempts = [svc.reserve(orderId, items)];
        if (random() < 0.3) attempts.push(svc.reserve(orderId, items));
        const reserved = await Promise.allSettled(attempts);
        if (reserved.every(r => r.status === 'rejected')) return reserved;
        const next = random() < 0.6 ? 'commit' : 'release';
        return Promise.allSettled([svc[next](orderId), random() < 0.3 ? svc[next](orderId) : null]);
      };

      const workers = Array.from({ length: 80 }, (_, i) => worker(`o${i}`));
      const background = [];
      for (let i = 0; i < 8; i++) {
        const sku = pick(skus);
        added[sku] += 3;
        background.push(svc.addStock(sku, 3), svc.expire());
      }
      await Promise.all(background);
      for (const outcomes of await Promise.all(workers)) {
        for (const r of outcomes) {
          if (r.status === 'rejected') {
            assert.ok(
              r.reason instanceof InsufficientStockError || r.reason instanceof OrderStateError,
              `unexpected rejection: ${r.reason.stack}`
            );
          }
        }
      }
      await assertConsistent(svc, store, added);
    });
  }
});

