timeout 20 node -e "
const { InventoryService, Store } = require('./src');
(async () => {
  const inner = new Store(); let stall = false, resume; const gate = new Promise(r => { resume = r; });
  const pass = async k => { if (stall && k === 'sku:slow') await gate; };
  const store = { async get(k) { await pass(k); return inner.get(k); }, async set(k, v) { await pass(k); return inner.set(k, v); }, keys: p => inner.keys(p) };
  const svc = new InventoryService({ store, reservationTtlMs: -1 });
  await svc.addStock('slow', 3); await svc.addStock('fast', 3);
  await svc.reserve('o-slow', [{ sku: 'slow', qty: 1 }]);
  stall = true;
  let expired = null; const job = svc.expire().then(ids => { expired = ids; });
  await svc.reserve('o-fast', [{ sku: 'fast', qty: 2 }]); await svc.commit('o-fast');
  console.log('fast done while expire stuck:', JSON.stringify(await svc.snapshot('fast')), 'expire finished?', expired !== null);
  resume(); await job;
  console.log('after resume expire returned', JSON.stringify(expired), JSON.stringify(await svc.snapshot('slow')));
})();"

